async function testTekrarDene() {
  try {
    await tekrarDene(async (i) => { denemeSayisi++; throw new Error('hata'); }, 3);
  } catch (e) {
    console.log('tekrarDene hata fırlattı:', denemeSayisi === 3 ? 'OK' : 'FAIL - ' + denemeSayisi);
